    "\n  query Agenda($editionId: ID!, $echeances: Boolean) {\n    agenda(editionId: $editionId, echeances: $echeances) {\n      peutGerer\n      edition {\n        id\n        nom\n        statut\n      }\n      elements {\n        cle\n        sorte\n        titre\n        jour\n        jourFin\n        description\n        dateCleId\n        version\n        tacheId\n        perimetreId\n        faite\n      }\n    }\n  }\n": types.AgendaDocument,
