    "\n  query EspaceBenevole($jeton: String!) {\n    espaceBenevole(jeton: $jeton) {\n      organisation\n      activite\n      nom\n      confirme\n      contact\n      ics\n      places {\n        ref\n        titre\n        jour\n        jourFin\n        heureDebut\n        heureFin\n        lieu\n        perimetre\n        consignes\n        confirmee\n      }\n      plages {\n        jour\n        jourFin\n        heureDebut\n        heureFin\n      }\n    }\n  }\n": types.EspaceBenevoleDocument,
    "\n  mutation ConfirmerParticipation($jeton: String!) {\n    confirmerParticipation(jeton: $jeton)\n  }\n": types.ConfirmerParticipationDocument,
