    "\n  query DroitFichesCommunes {\n    peutRedigerFichesCommunes\n  }\n": types.DroitFichesCommunesDocument,
    "\n  query MesTaches($editionId: ID!) {\n    moi {\n      id\n      affectations(editionId: $editionId) {\n        id\n        perimetre {\n          id\n          slug\n          nom\n          groupe\n          couleur\n          referents(editionId: $editionId) {\n            id\n            nom\n          }\n          avancement(editionId: $editionId) {\n            total\n            faites\n            abandonnees\n            enRetard\n            sansPersonne\n          }\n        }\n      }\n    }\n    mesTaches(editionId: $editionId) {\n      ...TacheChamps\n    }\n    tachesAPrendre(editionId: $editionId) {\n      ...TacheChamps\n    }\n  }\n": types.MesTachesDocument,
    "\n  query Organigramme {\n    organigramme {\n      edition {\n        id\n        nom\n      }\n      complet\n      adresses\n      contactActivite\n      admins {\n        personneId\n        nom\n        adresse\n        moi\n      }\n      perimetres {\n        perimetre {\n          id\n          slug\n          nom\n          groupe\n          couleur\n        }\n        referents {\n          personneId\n          nom\n          adresse\n          contactPrincipal\n          moi\n        }\n      }\n    }\n  }\n": types.OrganigrammeDocument,
    "\n  query PagePerimetre($slug: String!, $editionId: ID!) {\n    moi {\n      id\n    }\n    perimetre(slug: $slug) {\n      id\n      nom\n      description\n      groupe\n      couleur\n      acces\n      peutModifier(editionId: $editionId)\n      referents(editionId: $editionId) {\n        id\n        nom\n      }\n      contactPrincipal(editionId: $editionId) {\n        id\n      }\n      avancement(editionId: $editionId) {\n        total\n        aFaire\n        enCours\n        faites\n        abandonnees\n        enRetard\n        sansPersonne\n      }\n      taches(editionId: $editionId) {\n        ...TacheChamps\n        # Tâches partagées (ADR 0026) : pour une déclinaison, le périmètre qui la\n        # demande ; pour une tâche partagée, où en sont ses déclinaisons.\n        origine {\n          id\n          perimetre {\n            slug\n            nom\n            couleur\n          }\n        }\n        resumeDeclinaisons {\n          total\n          enAttente\n          refusees\n          acceptees\n          faites\n          abandonnees\n        }\n      }\n    }\n    fichesCommunes: fiches {\n      id\n      titre\n      perimetre {\n        id\n      }\n    }\n  }\n": types.PagePerimetreDocument,
    "\n  query FichesDuPerimetre($slug: String!) {\n    perimetre(slug: $slug) {\n      id\n      peutRedigerFiches\n      fiches {\n        id\n        slug\n        titre\n      }\n      # Les fiches d'autres périmètres qui concernent celui-ci (ADR 0039), masquées\n      # comprises : l'écran sépare les deux listes.\n      peutMasquerFichesConnexes\n      fichesConnexes(inclureMasquees: true) {\n        id\n        slug\n        titre\n        perimetre {\n          id\n          nom\n          couleur\n        }\n        connexions {\n          masquee\n          perimetre {\n            id\n          }\n        }\n      }\n    }\n  }\n": types.FichesDuPerimetreDocument,
    "\n  query MesPreferencesNotification {\n    mesPreferencesNotification {\n      frequenceResume\n      mailModification\n      mailEcheance\n      mailDemandes\n      applicationPerimetre\n      pushTaches\n      pushEcheances\n      pushDemandes\n      pushEquipe\n      pushAgenda\n      applicationEquipe\n      resumeAdmin\n    }\n  }\n": types.MesPreferencesNotificationDocument,
    "\n  mutation ModifierPreferencesNotification(\n    $frequenceResume: FrequenceResume!\n    $mailModification: Boolean!\n    $mailEcheance: Boolean!\n    $mailDemandes: Boolean\n    $applicationPerimetre: Boolean\n    $applicationEquipe: Boolean\n    $resumeAdmin: Boolean\n  ) {\n    modifierPreferencesNotification(\n      frequenceResume: $frequenceResume\n      mailModification: $mailModification\n      mailEcheance: $mailEcheance\n      mailDemandes: $mailDemandes\n      applicationPerimetre: $applicationPerimetre\n      applicationEquipe: $applicationEquipe\n      resumeAdmin: $resumeAdmin\n    ) {\n      frequenceResume\n      mailModification\n      mailEcheance\n      mailDemandes\n      applicationPerimetre\n      applicationEquipe\n      resumeAdmin\n    }\n  }\n": types.ModifierPreferencesNotificationDocument,
