    "\n  query Programme($editionId: ID!, $mesSequences: Boolean) {\n    programme(editionId: $editionId, mesSequences: $mesSequences) {\n      id\n      editionId\n      titre\n      description\n      besoinBenevoles\n      consignesBenevoles\n      renforts\n      jour\n      jourFin\n      heureDebut\n      heureFin\n      version\n      peutModifier\n      perimetre {\n        id\n        nom\n        couleur\n      }\n      lieu {\n        id\n        nom\n      }\n      places {\n        id\n        role\n        personneId\n        benevoleId\n        nom\n        estMoi\n        etat\n      }\n    }\n  }\n": types.ProgrammeDocument,
    "\n  query FormulaireRejoindre($organisation: String, $activite: String!) {\n    formulaireRejoindre(organisation: $organisation, activite: $activite) {\n      organisation\n      activite\n      periode\n      introduction\n      question\n      paliers\n      contact\n      groupes {\n        libelle\n        perimetres {\n          slug\n          nom\n          description\n          couleur\n        }\n      }\n    }\n  }\n": types.FormulaireRejoindreDocument,
    "\n  mutation EnvoyerDemande(\n    $organisation: String\n    $activite: String!\n    $nom: String!\n    $email: String!\n    $perimetres: [String!]!\n    $disponibilite: String\n    $reponse: String\n    $texte: String\n    $siteWeb: String\n  ) {\n    envoyerDemande(\n      organisation: $organisation\n      activite: $activite\n      nom: $nom\n      email: $email\n      perimetres: $perimetres\n      disponibilite: $disponibilite\n      reponse: $reponse\n      texte: $texte\n      siteWeb: $siteWeb\n    )\n  }\n": types.EnvoyerDemandeDocument,
    "\n  query Retroplanning($editionId: ID!) {\n    moi {\n      id\n      estAdmin\n      affectations(editionId: $editionId) {\n        id\n        perimetre {\n          id\n        }\n      }\n    }\n    retroplanning(editionId: $editionId) {\n      id\n      titre\n      echeance\n      statut\n      enRetard\n      perimetre {\n        id\n        slug\n        nom\n        groupe\n        couleur\n        ordre\n      }\n      assignes {\n        id\n        nom\n      }\n      # Pour réunir les déclinaisons d'une même tâche partagée (ADR 0026).\n      origine {\n        id\n      }\n    }\n  }\n": types.RetroplanningDocument,
